import{$f as e,Zf as t}from"../../../content-es-meta-er8sy6l1.js";var n=t();function r(t){let r={a:"a",em:"em",h2:"h2",h3:"h3",li:"li",ol:"ol",p:"p",strong:"strong",ul:"ul",...e(),...t.components},{Callout:i,GenericPrompt:o}=r;return i||a("Callout",!0),o||a("GenericPrompt",!0),(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(r.h2,{id:"what-is-an-ai-diligence-statement",children:"What is an AI diligence statement?"}),`
`,(0,n.jsxs)(r.p,{children:[`An AI diligence statement is a transparent acknowledgment of AI's role in your work, paired with your commitment to taking responsibility for the final output. Think of it as the "methods section" for your AI collaboration: it explains what AI did, what you did, and how you verified the result. Learn more about Diligence and the 4D framework for AI Fluency `,(0,n.jsx)(r.a,{href:"/courses/ai-fluency-framework-foundations",children:"here"}),"."]}),`
`,(0,n.jsx)(r.p,{children:"Here’s an example for this tutorial:"}),`
`,(0,n.jsx)(i,{type:"note",children:(0,n.jsx)(r.p,{children:"In creating this tutorial, I collaborated with Claude to assist with synthesis, voice, tone, and format. I affirm that all AI-generated and co-created content underwent thorough review and evaluation. The final output accurately reflects my understanding, expertise, and intended meaning. While AI assistance was instrumental in the process, I maintain full responsibility for the content, its accuracy, and its presentation. This disclosure is made in the spirit of transparency and to acknowledge the role of AI in the creation process."})}),`
`,(0,n.jsx)(r.h2,{id:"why-write-one",children:"Why write one?"}),`
`,(0,n.jsx)(r.p,{children:"AI use in professional work is becoming common, but norms around disclosure are still forming. In many fields, especially regulated industries like life sciences, finance, and education, transparency about AI involvement is increasingly expected or required."}),`
`,(0,n.jsxs)(r.p,{children:["A good AI diligence statement does several things at once. It builds trust with your audience by showing you are thoughtful about how you use AI. It demonstrates professional judgment by documenting your verification process. It protects you by creating a clear record of your role in the final output. And it contributes to organizational learning by making AI use visible so teams can develop shared standards. For organizations to become fluent with AI, transparency is key. If it feels scary to disclose AI use, it’s unlikely the environment will be conducive to transformation. You can learn more about the importance of diligence in ",(0,n.jsx)(r.a,{href:"https://www.youtube.com/watch?v=QbLf2zb3oPc",children:"this video"})," from our AI Fluency & Foundations course."]}),`
`,(0,n.jsx)(r.h2,{id:"anatomy-of-a-strong-ai-diligence-statement",children:"Anatomy of a strong AI diligence statement"}),`
`,(0,n.jsx)(r.p,{children:"Strong AI diligence statements share a few characteristics. They are specific about what AI was used for, they describe the human review process, and they make clear who is accountable for the final product."}),`
`,(0,n.jsx)(r.h3,{id:"five-elements-to-include",children:"Five elements to include"}),`
`,(0,n.jsxs)(r.ol,{children:[`
`,(0,n.jsxs)(r.li,{children:[`
`,(0,n.jsxs)(r.p,{children:[(0,n.jsx)(r.strong,{children:"What AI assisted with."}),` Name the specific tasks: drafting, research synthesis, data analysis, editing, formatting. Vague language like "AI contributed to this work" doesn't tell your reader anything useful.`]}),`
`]}),`
`,(0,n.jsxs)(r.li,{children:[`
`,(0,n.jsxs)(r.p,{children:[(0,n.jsx)(r.strong,{children:"Which AI tool you used."}),' Identify the model or platform. "Claude" is more informative than "an AI assistant." If you used multiple tools, say so.']}),`
`]}),`
`,(0,n.jsxs)(r.li,{children:[`
`,(0,n.jsxs)(r.p,{children:[(0,n.jsx)(r.strong,{children:"What you reviewed and your general involvement."})," How did you drive the process with AI? How did you give the AI feedback and give it the right context? Describe your verification process. Did you fact-check claims against primary sources? Cross-reference statistics? Have a colleague review the output? The specifics matter."]}),`
`]}),`
`,(0,n.jsxs)(r.li,{children:[`
`,(0,n.jsxs)(r.p,{children:[(0,n.jsx)(r.strong,{children:"What you changed."})," Note where you applied your own expertise to revise, add to, or override AI-generated content. This is where your professional judgment is most visible."]}),`
`]}),`
`,(0,n.jsxs)(r.li,{children:[`
`,(0,n.jsxs)(r.p,{children:[(0,n.jsx)(r.strong,{children:"Who is responsible."})," Affirm that you stand behind the final output. This is the accountability piece that turns a disclosure into a commitment."]}),`
`]}),`
`]}),`
`,(0,n.jsx)(r.h2,{id:"creating-an-ai-diligence-statement-with-ai",children:"Creating an AI diligence statement with AI"}),`
`,(0,n.jsx)(r.p,{children:"You can use any AI tool to help you draft an AI diligence statement for a project where AI played a role. The process takes about 10 minutes and works best when you bring specifics about your project and your review process."}),`
`,(0,n.jsx)(r.h3,{id:"step-1-describe-the-project-and-ais-role",children:"Step 1: Describe the project and AI's role"}),`
`,(0,n.jsx)(r.p,{children:"Start by telling AI about your project and how you used AI in it. Be specific about the tasks. The more detail you provide here, the more precise and useful the resulting AI diligence statement will be."}),`
`,(0,n.jsx)(r.p,{children:(0,n.jsx)(r.strong,{children:"Example prompt:"})}),`
`,(0,n.jsx)(o,{children:(0,n.jsx)(r.p,{children:"I need to write an AI diligence statement for a competitive landscape analysis I just completed. Here's how I used AI in the process: I used Claude to synthesize publicly available information about five competitor companies in the oncology therapeutics space. Specifically, I asked Claude to summarize each company's pipeline status, recent clinical trial results, and strategic partnerships based on information I provided from SEC filings, press releases, and published trial data. I then reviewed each summary against the original source documents, corrected two instances where Claude mischaracterized the phase of a clinical trial, added our internal team's strategic interpretation that Claude wouldn't have access to, and restructured the competitive positioning section based on conversations with our BD team. Please draft an AI diligence statement I can include at the end of this report. Keep it concise but specific."})}),`
`,(0,n.jsx)(r.h3,{id:"step-2-review-and-refine-the-draft",children:"Step 2: Review and refine the draft"}),`
`,(0,n.jsx)(r.p,{children:"The AI tool you’ve selected will produce a first draft. Review it to make sure it accurately describes your process. Common things to refine include adjusting the scope (did it capture all the tasks you described, or miss some?), adding specific details about your verification steps, and making sure the statement reflects your field's norms and expectations."}),`
`,(0,n.jsx)(r.p,{children:(0,n.jsx)(r.strong,{children:"Example follow-up prompt:"})}),`
`,(0,n.jsx)(o,{children:(0,n.jsx)(r.p,{children:"This is close, but I want to add that our VP of Clinical Development also reviewed the trial data summaries before I finalized the report. And can you make the language about my corrections more specific? I want to note that the corrections were about trial phase classifications, not about the underlying data."})}),`
`,(0,n.jsx)(r.h3,{id:"step-3-adapt-for-your-audience",children:"Step 3: Adapt for your audience"}),`
`,(0,n.jsx)(r.p,{children:"Different audiences need different levels of detail. An AI diligence statement in an internal strategy document might be brief, while one accompanying a regulatory submission should be thorough. Ask AI to adjust."}),`
`,(0,n.jsx)(r.p,{children:(0,n.jsx)(r.strong,{children:"Example prompt:"})}),`
`,(0,n.jsx)(o,{children:(0,n.jsx)(r.p,{children:"Can you create two versions of this AI diligence statement? One for the full internal report (2-3 paragraphs with specific details about the review process) and one shorter version for the executive summary slide deck (2-3 sentences that capture the essentials)."})}),`
`,(0,n.jsx)(r.h3,{id:"step-4-verify-the-ai-diligence-statement-itself",children:"Step 4: Verify the AI diligence statement itself"}),`
`,(0,n.jsx)(r.p,{children:`This is an important step that's easy to skip. Read the AI diligence statement carefully and make sure it accurately represents what happened. If the statement says you "verified all citations," make sure that's true. If it says you "cross-referenced with primary sources," confirm that's what you actually did. Your AI diligence statement is itself a claim about your process, and it needs to be accurate.`}),`
`,(0,n.jsx)(r.h2,{id:"building-an-organizational-culture-of-diligence",children:"Building an organizational culture of diligence"}),`
`,(0,n.jsx)(r.p,{children:"Diligence statements only work if people feel safe writing them. If disclosing AI use feels risky, whether because of unclear policies, judgment from colleagues, or fear that it diminishes the perceived value of their work, people will either stop using AI or stop being honest about it. Both outcomes are worse than transparent use."}),`
`,(0,n.jsx)(r.p,{children:"Leaders set the tone here. When a manager includes a diligence statement on their own deliverables, it signals that disclosure is a professional norm, not an admission of weakness. When a team lead shares how AI helped them draft a strategy document and what they changed during review, it gives others a concrete model to follow. Transparency is contagious, but it has to start somewhere visible."}),`
`,(0,n.jsx)(r.p,{children:"A few practical steps for organizations:"}),`
`,(0,n.jsxs)(r.ul,{children:[`
`,(0,n.jsxs)(r.li,{children:[`
`,(0,n.jsx)(r.p,{children:"Make diligence statements part of your templates and workflows rather than an afterthought."}),`
`]}),`
`,(0,n.jsxs)(r.li,{children:[`
`,(0,n.jsx)(r.p,{children:"Celebrate thorough disclosures the same way you'd celebrate thorough methods sections in research."}),`
`]}),`
`,(0,n.jsxs)(r.li,{children:[`
`,(0,n.jsx)(r.p,{children:"Avoid policies that treat AI use as inherently suspect. The goal is responsible use, and responsibility requires honesty. If your culture penalizes honesty, you won't get responsibility either."}),`
`]}),`
`]}),`
`,(0,n.jsx)(r.h2,{id:"frequently-asked-questions-about-ai-diligence-statements",children:"Frequently asked questions about AI diligence statements"}),`
`,(0,n.jsxs)(r.ol,{children:[`
`,(0,n.jsxs)(r.li,{children:[`
`,(0,n.jsxs)(r.p,{children:[(0,n.jsx)(r.strong,{children:"How do I trust what AI gives me?"})," AI is capable, but it does have limitations. The key is to adjust your level of scrutiny based on what you're asking, what the stakes are, and how verifiable the output is. Ask for sources and check them. Run the same question multiple ways and look for consistency. For document-based tasks, ask the AI to quote directly from source material rather than paraphrase. Check out our videos on hallucination and bias for a deeper dive."]}),`
`]}),`
`,(0,n.jsxs)(r.li,{children:[`
`,(0,n.jsxs)(r.p,{children:[(0,n.jsx)(r.strong,{children:"Do I have to stand behind everything I make with AI?"})," You can use AI for many different reasons and many different use cases. You decide if you stand behind it. For example, you might say “I asked Claude to summarize this article. Here’s the summary; read it with discernment.” In that way, the diligence statement helps you signal how other people should approach the work and giving you the flexibility to decide the level of review provided to all tasks you conduct with AI. Every aspect of AI Fluency, including this one, is about putting you in the driver’s seat."]}),`
`]}),`
`,(0,n.jsxs)(r.li,{children:[`
`,(0,n.jsxs)(r.p,{children:[(0,n.jsx)(r.strong,{children:"What if my organization doesn’t have a policy on AI disclosure?"})," That's actually a good reason to start writing diligence statements now. You'll be establishing a personal standard of transparency, and your practice can inform the organizational policy when it comes. Share your approach with your manager or team. Early adopters often end up shaping the norms."]}),`
`]}),`
`,(0,n.jsxs)(r.li,{children:[`
`,(0,n.jsxs)(r.p,{children:[(0,n.jsx)(r.strong,{children:"Does including an AI diligence statement on my work make it seem less credible?"})," The opposite, in most cases. A specific diligence statement demonstrates that you were thoughtful about your process, that you verified the output, and that you're confident enough in the result to describe exactly how it was made. Vague or absent disclosure is what erodes trust, especially if someone discovers the AI involvement later."]}),`
`]}),`
`,(0,n.jsxs)(r.li,{children:[`
`,(0,n.jsxs)(r.p,{children:[(0,n.jsx)(r.strong,{children:"Can I reuse AI diligence statements across projects?"})," You can use a consistent structure, but the content should be specific to each project. A template that you fill in with project-specific details (what AI did, what you reviewed, what you changed) is the right approach. A copy-pasted generic statement that doesn't describe your actual process provides very little value."]}),`
`]}),`
`]}),`
`,(0,n.jsx)(r.h2,{id:"wrapping-up",children:"Wrapping up"}),`
`,(0,n.jsx)(r.p,{children:"Writing AI diligence statements and taking full responsibility for AI’s outputs is a key component of AI Fluency. Normalizing this practice will help ensure we all build intentional relationships with AI use in a variety of settings."}),`
`,(0,n.jsxs)(r.p,{children:[(0,n.jsx)(r.em,{children:"This tutorial is part of the AI Fluency effort at Anthropic. It was designed to help professionals develop practical, responsible approaches to AI collaboration. Learn more at"})," ",(0,n.jsx)(r.a,{href:"/courses/ai-fluency-framework-foundations",children:(0,n.jsx)(r.em,{children:"Claude Academy"})}),(0,n.jsx)(r.em,{children:"."})]})]})}function i(t={}){let{wrapper:i}={...e(),...t.components};return i?(0,n.jsx)(i,{...t,children:(0,n.jsx)(r,{...t})}):r(t)}function a(e,t){throw Error("Expected "+(t?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}export{i as default};